 <section class="admin-card"><div class="admin-section-heading"><div><span class="admin-overline">CAUTIONS</span><h2>Reversements confirmés</h2></div></div><div class="admin-table-wrap"><table><thead><tr><th>Confirmé UTC</th><th>Location</th><th>Remboursé</th><th>Retenue</th></tr></thead><tbody><?php foreach($report['refunds'] as $row): ?><tr><td><?= $escape($row['confirmed_at']) ?></td><td><?= $escape($row['reference']) ?></td><td><?= $money((int)$row['refund_amount']) ?></td><td><?= $money((int)$row['deduction']) ?></td></tr><?php endforeach; ?><?php if(!$report['refunds']): ?><tr><td colspan="4">Aucun reversement confirmé et daté sur la période.</td></tr><?php endif; ?></tbody></table></div><p class="finance-hint">Les reversements historiques antérieurs à l'installation de ce module n'ont pas de date de confirmation fiable et ne figurent pas dans le total de la période.</p></section>
